"""Derive review appendices from fresh captured bytes; never run adapters."""
import ast
import hashlib
import json
from pathlib import Path
import re
import sys

OUT = Path(__file__).resolve().parent
ROOT = OUT.parents[2]


def save(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2, sort_keys=True) + '\n')


main = json.loads((OUT / 'objects.json').read_text())
extra = json.loads((OUT / 'supplement-objects.json').read_text())
all_objects = dict(main)
for path, row in extra.items():
    if path in all_objects:
        assert row['sha256'] == all_objects[path]['sha256'], path
    else:
        all_objects[path] = {**row, 'scopes': [row['scope']]}
all_objects = dict(sorted(all_objects.items()))
identities = {p: 'H%04d' % (i + 1) for i, p in enumerate(all_objects)}

# Every resolved object is enumerated once, with native provider edges and all
# its inspection scopes. No scope is promoted to actual scoring evidence.
lines = ['# Native object digest appendix - w-hostdeps', '',
         'Generated by derive.py from raw ldd/readelf and independent sha256sum captures.',
         'A digest pins recorded file bytes; scopes distinguish import observations from installed supersets.',
         'Every provider edge below comes from that object\'s raw ldd output; DT_NEEDED/INTERP are in objects.json or supplement-objects.json.', '',
         '| ID | Resolved file | SHA-256 | Inspection scope | Resolved provider IDs / unresolved SONAMEs |',
         '| --- | --- | --- | --- | --- |']
for p, row in all_objects.items():
    scopes = row.get('scopes', [row.get('scope', '')])
    providers = [identities[q] for q in row.get('resolved_providers', [])]
    unresolved = row.get('unresolved_sonames', [])
    lines.append('| %s | `%s` | `%s` | %s | %s |' % (
        identities[p], p, row['sha256'], '<br>'.join(scopes),
        ', '.join(providers) + ('; UNRESOLVED: ' + ', '.join(unresolved) if unresolved else '')))
(OUT / 'native-dependencies.md').write_text('\n'.join(lines) + '\n')

# DS eligible context roots are recalculated exactly from literal exclusions
# and the current adapter regex, without importing it or copying answer bodies.
adapter = ast.parse((ROOT / 'data/datasets/ds1000.py').read_text())
exclusions = None
for node in adapter.body:
    if isinstance(node, ast.AnnAssign) and getattr(node.target, 'id', None) == 'MEASURED_EXCLUSIONS':
        exclusions = ast.literal_eval(node.value)
assert exclusions is not None
fixed = {i for indices in exclusions.values() for i in indices}
tf = re.compile(r'\b(import tensorflow|from tensorflow|tf\.)')
path = Path('/mnt/20t/xubuqiang/datasets/ds1000/_src/test.jsonl')
roots = {}
all_roots = {}
excluded_rows = []
total_rows = 0
for index, raw in enumerate(path.read_text().splitlines()):
    row = json.loads(raw)
    total_rows += 1
    code = row['code_context']
    excluded = index in fixed or bool(tf.search(code))
    if excluded:
        excluded_rows.append(index)
    for node in ast.walk(ast.parse(code)):
        if isinstance(node, ast.Import):
            names = [a.name.split('.')[0] for a in node.names]
        elif isinstance(node, ast.ImportFrom):
            names = [str(node.module).split('.')[0]]
        else:
            continue
        for name in names:
            if name in sys.stdlib_module_names:
                continue
            record = {'source': str(path), 'file_line': index + 1, 'context_line': node.lineno,
                      'text': code.splitlines()[node.lineno - 1]}
            all_roots.setdefault(name, record)
            if not excluded:
                roots.setdefault(name, record)
save('ds1000-eligible-imports.json', {'total_rows_read': total_rows, 'eligible_rows': total_rows - len(excluded_rows),
     'eligible_external_import_roots': roots, 'all_external_import_roots': all_roots,
     'excluded_rows': excluded_rows, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
     'scope': 'trusted context imports only; arbitrary candidate imports/subprocesses remain unknown'})

distributions = json.loads((OUT / 'distributions.json').read_text())
facts = {'unique_digest_recorded_files': len(all_objects),
         'unique_elf_files': sum(r.get('elf', False) for r in all_objects.values()),
         'pinned_complete_native_surfaces': {'numerator': 0, 'denominator': 7},
         'datasets_with_partial_digest_inventory': {'numerator': 7, 'denominator': 7},
         'ds1000_eligible_context_external_roots': roots,
         'observed_distribution_versions': {n: r.get('version') for n, r in distributions['records'].items()},
         'object_ids': identities,
         'unresolved_standalone': {p: r['unresolved_sonames'] for p, r in all_objects.items() if r.get('unresolved_sonames')}}
save('facts.json', facts)
print(json.dumps({k: v for k, v in facts.items() if k != 'object_ids'}, indent=2))
